insert into public.courses (id, sort_order, title, description) values
  ('fundamentals', 1, 'Electronics fundamentals', 'Voltage, current, resistance, components and using a multimeter.'),
  ('power', 2, 'Smartphone power systems', 'Battery, charging, PMIC, rails and current-draw diagnosis.'),
  ('boot', 3, 'Boot sequence and startup', 'From power key press to the OS: what happens and in what order.'),
  ('clocks', 4, 'Clocks and reset', 'Crystals, oscillators, reset lines and why they stop a board booting.'),
  ('memory', 5, 'RAM and storage', 'LPDDR, eMMC, UFS, stacked packages and memory-related faults.'),
  ('buses', 6, 'SoC and peripheral communication', 'I²C, SPI, MIPI and how the SoC talks to everything else.'),
  ('platforms', 7, 'Platform-specific architecture', 'How MediaTek, Snapdragon, Exynos, UNISOC and Apple designs differ.'),
  ('diagnosis', 8, 'Practical fault diagnosis', 'A systematic workflow from symptom to verified repair.')
insert into public.lessons (id, course_id, slug, sort_order, title, summary, minutes, difficulty, status, objectives, blocks) values
  ('fundamentals/voltage-current-resistance', 'fundamentals', 'voltage-current-resistance', 1, 'Voltage, current and resistance', 'The three quantities behind every fault you will diagnose, and how Ohm''s law links them.', 10, 'beginner', 'published', array['Explain voltage, current and resistance in plain terms', 'Use Ohm''s law to work out one value from the other two', 'Explain why a short circuit draws high current and an open circuit draws none']::text[], '[{"type":"text","text":"Almost every phone fault, from a dead board to a camera that won''t open, comes down to three quantities: voltage, current and resistance. If you understand how they relate, measurements stop being random numbers and start telling you a story."},{"type":"heading","text":"Voltage: the push"},{"type":"text","text":"Voltage (measured in volts, V) is the difference in electrical pressure between two points. It is what pushes current through a circuit. A voltage is always measured between two points. On a phone board, that is usually between a test point and ground."},{"type":"heading","text":"Current: the flow"},{"type":"text","text":"Current (measured in amps, A) is how much electric charge flows past a point each second. Phone currents are often small, so you will see milliamps (mA): 1 A = 1000 mA."},{"type":"heading","text":"Resistance: the opposition"},{"type":"text","text":"Resistance (measured in ohms, Ω) is how strongly something opposes current. A thin, long path has more resistance than a short, thick one. Components such as resistors are made to have a specific resistance."},{"type":"callout","tone":"key","title":"Ohm''s law","text":"V = I × R. Rearranged, I = V ÷ R and R = V ÷ I. If you know any two values, you can work out the third."},{"type":"example","title":"Worked example (textbook numbers, not a phone measurement)","steps":["A 4 V supply is connected across a 2 Ω resistance.","Current I = V ÷ R = 4 ÷ 2 = 2 A.","Now imagine the resistance drops to 0.1 Ω, like a near-short. I = 4 ÷ 0.1 = 40 A, far more than the circuit is designed to carry."],"note":"In a real circuit, the supply''s current limit, the battery and the short''s actual resistance limit the current. The energy usually turns into heat at the shorted spot, which is why shorted parts get warm."},{"type":"heading","text":"Why this matters for repair"},{"type":"list","items":["A short circuit is a very low-resistance path, so current rises sharply. That is why a shorted capacitor heats up and why a bench power supply shows high current.","An open circuit (a broken track, cracked solder joint or torn flex) has very high resistance, so no current flows and the part beyond the break gets no power.","Power is P = V × I. The heat you feel at a fault is power being turned into heat at that spot."]},{"type":"callout","tone":"tip","title":"Ground is your reference","text":"Most measurements on a phone board are taken relative to ground. Shield frames and screw points are often grounded, but always confirm a ground point on the schematic or boardview for that model."}]'::jsonb),
  ('fundamentals/multimeter-basics', 'fundamentals', 'multimeter-basics', 2, 'Using a multimeter safely', 'Choose the right mode, measure voltage correctly, and avoid damaging the meter or the board.', 12, 'beginner', 'published', array['Choose the right multimeter mode for each test', 'Know which tests need the board powered and which need it unpowered', 'Measure a DC voltage step by step and record the conditions']::text[], '[{"type":"text","text":"A digital multimeter is your main diagnostic tool. Used well, it tells you whether power is arriving, whether a line is shorted, and whether a connection is broken. Used carelessly, it gives misleading readings or causes new damage."},{"type":"heading","text":"The modes you will use most"},{"type":"list","items":["DC voltage (V⎓): measured with the board powered, probes across two points (usually a test point and ground).","Resistance (Ω): the board must be unpowered.","Continuity (beep): checks for a very low-resistance path, for example along a flex cable or track. The board must be unpowered.","Diode mode: the most-used unpowered test in board repair. It has its own lesson next.","Current (A / mA): the meter must be placed in series with the circuit. On phone boards, a bench power supply''s current display is usually more practical."]},{"type":"callout","tone":"caution","title":"Never use resistance, continuity or diode mode on a powered board","text":"In these modes the meter applies its own small voltage. On a powered board the readings are meaningless, and you can damage the meter or the board. Disconnect the battery and charger first."},{"type":"callout","tone":"caution","title":"Current mode is almost a short circuit","text":"In current mode the meter''s input has very low resistance. Placing the probes across a supply shorts it, which can blow the meter''s fuse or damage the board. Move the red lead back to the V/Ω jack after measuring current."},{"type":"heading","text":"Measuring a DC voltage"},{"type":"example","title":"Procedure","steps":["Set the meter to DC voltage.","Place the black probe on a confirmed ground point.","Power the board in the state the test requires (off, booting, on, charging).","Touch the red probe to the test point, holding it steady so it can''t slip onto a neighbouring pad.","Compare the reading with the schematic or a known-good board of the same model, measured in the same state."],"note":"Always record the phone''s state with each reading. Many rails switch on and off depending on whether the phone is off, booting, running or charging."},{"type":"callout","tone":"tip","title":"Use fine probe tips","text":"Phone components are tiny and close together. Sharp, fine tips reduce slipping. On a powered board, a probe slipping between two pads can create a new short."}]'::jsonb),
  ('fundamentals/diode-mode', 'fundamentals', 'diode-mode', 3, 'Diode mode: finding shorts safely', 'Use diode mode on an unpowered board to find shorted lines, and compare readings the right way.', 12, 'beginner', 'published', array['Explain what a diode-mode reading represents on a phone board', 'Recognise a short to ground and an open line', 'Compare readings correctly against a known-good board']::text[], '[{"type":"text","text":"Diode mode is the most-used measurement in board repair because it works with the board unpowered. That makes it safe to use on a phone that might have a short, before you risk applying power."},{"type":"heading","text":"What the meter is doing"},{"type":"text","text":"In diode mode the meter pushes a small, limited test current and displays the voltage needed to push it. Across a single diode you would see its forward voltage drop. On a phone board you are measuring the combined path through everything connected to that point."},{"type":"diagram","diagram":"diode-mode","caption":"Conceptual: the meter measures the path between a test point and ground through everything connected to that line."},{"type":"heading","text":"Reading the result"},{"type":"list","items":["Very close to zero: the line is shorted, or nearly shorted, to ground.","A value that looks normal: compare it with the same point on a known-good board before deciding.","OL (over limit): no conducting path within the meter''s range. This is normal for some lines and a sign of a broken connection on others."]},{"type":"callout","tone":"key","title":"Compare, don''t guess","text":"There is no universal correct diode reading. Values depend on the board, the meter and the probe orientation. Only compare against the same point on a known-good board of the same model, using the same meter and the same probe orientation."},{"type":"heading","text":"Probe orientation"},{"type":"text","text":"Many technicians put the red probe on ground and the black probe on the test point. Others use the opposite. The two orientations give different readings. Pick one, use it every time, and write down which one you used."},{"type":"example","title":"Finding a short on a supply line","steps":["Disconnect the battery and charger, and give capacitors a moment to discharge.","Set diode mode. Put one probe on ground and the other on a capacitor on the suspect line.","A reading near zero means the line is shorted to ground.","Use the schematic or boardview to list everything connected to that line.","Locate the faulty part, for example with a thermal camera, rosin or freeze spray while carefully injecting a limited current, or by isolating parts one at a time."],"note":"Current injection must be done carefully. Keep the voltage and current limits low and suitable for that line according to its schematic. Injecting into the wrong line can damage working components."},{"type":"explorer","blockId":"pmic","text":"Most shorts you find this way are on PMIC output rails or the battery supply line. See how they connect in the Chipset Explorer."}]'::jsonb),
  ('fundamentals/capacitors', 'fundamentals', 'capacitors', 4, 'Capacitors and why they short', 'What capacitors do on a phone board and how they fail.', 10, 'beginner', 'planned', '{}'::text[], '[]'::jsonb),
  ('fundamentals/inductors-and-coils', 'fundamentals', 'inductors-and-coils', 5, 'Inductors and coils', 'Where inductors appear in power circuits and how to check them.', 8, 'beginner', 'planned', '{}'::text[], '[]'::jsonb),
  ('fundamentals/diodes-and-protection', 'fundamentals', 'diodes-and-protection', 6, 'Diodes and protection parts', 'Diodes, TVS and ESD protection: what they guard against.', 10, 'beginner', 'planned', '{}'::text[], '[]'::jsonb),
  ('fundamentals/transistors-and-mosfets', 'fundamentals', 'transistors-and-mosfets', 7, 'Transistors and MOSFETs as switches', 'How switching components turn loads on and off.', 12, 'intermediate', 'planned', '{}'::text[], '[]'::jsonb),
  ('fundamentals/reading-schematics-and-boardviews', 'fundamentals', 'reading-schematics-and-boardviews', 8, 'Reading schematics and boardviews', 'Finding a line, its components and its test points.', 14, 'intermediate', 'planned', '{}'::text[], '[]'::jsonb),
  ('power/power-path', 'power', 'power-path', 1, 'From battery to rails: the power path', 'Follow power from the USB port and battery through the PMIC to the rails that feed every part of the phone.', 12, 'beginner', 'published', array['Trace the conceptual power path from USB input to the loads', 'Explain the difference between the main supply line and PMIC rails', 'Explain why a short on the main supply line makes a phone appear dead']::text[], '[{"type":"text","text":"A phone doesn''t run everything directly from the battery. Power passes through several stages, and each one changes or protects it. Knowing the stages tells you where to measure first."},{"type":"diagram","diagram":"power-path","caption":"Conceptual power path. Real designs differ in the number of PMICs, which loads use the main supply line directly, and how the charging IC connects."},{"type":"heading","text":"Stage by stage"},{"type":"list","ordered":true,"items":["USB input: the charging port, filtering, and protection such as over-voltage protection on many designs.","Charging IC: charges the battery and, on many designs, also supplies the system.","Battery and battery connector.","Main system supply line: feeds the PMIC(s) and, on many designs, some high-power loads directly. Its name varies by platform, so read it from the schematic.","PMIC(s): buck converters and LDO regulators turn the main supply into many lower-voltage rails.","Rails to loads: the SoC, memory, display, cameras and other parts."]},{"type":"heading","text":"Buck converters and LDOs"},{"type":"text","text":"A buck converter switches on and off very quickly and uses an inductor to step voltage down efficiently. That is why you see inductors (coils) around a PMIC. An LDO (low-dropout regulator) steps voltage down without switching. It is simpler and quieter but less efficient, so it is often used for sensitive or low-current rails."},{"type":"callout","tone":"key","title":"Why a short on the main supply line matters","text":"Everything downstream is fed from the main supply line. A short there usually makes the phone appear dead, and a bench power supply may show current as soon as it is connected, before you press power."},{"type":"callout","tone":"caution","title":"No universal rail values","text":"Rail names, voltages and which rails exist all vary by model and board revision. Take expected values from that model''s schematic or a known-good board, never from another phone."},{"type":"explorer","blockId":"charging","text":"See how Battery & Charging and the PMIC connect in the Chipset Explorer."}]'::jsonb),
  ('power/dc-power-supply-current-draw', 'power', 'dc-power-supply-current-draw', 2, 'Reading current draw on a DC power supply', 'Use a bench power supply safely and learn the general current patterns that point toward a fault area.', 14, 'intermediate', 'published', array['Connect a bench power supply safely', 'Recognise common current-draw patterns', 'Link each pattern to the boot stage and fault areas to check next']::text[], '[{"type":"text","text":"A bench DC power supply can stand in for the battery and show how much current the phone draws, moment by moment. Watching that number while you press power is one of the fastest ways to narrow down a dead phone."},{"type":"callout","tone":"caution","title":"Set up safely","text":"Use a voltage within the rated range of that model''s battery (check the battery label or service information). Start with a low current limit and raise it only when needed. Check polarity before connecting, because reversed polarity can destroy components. Use a proper adapter that fits the battery connector."},{"type":"heading","text":"Common patterns"},{"type":"text","text":"These are general starting points, not diagnoses. Normal current behaviour differs between models, so always compare with a known-good phone of the same model."},{"type":"list","items":["Current flows as soon as you connect, before pressing power, and may hit the limit: suggests a short on the main supply line or something connected to it.","No current at all when pressing power: the power-on trigger may not be reaching the PMIC, or the PMIC is not starting. Check the power key line, the battery connector and the supply path.","A small jump that falls straight back to zero: the power-on sequence starts but stops. Possible causes include a missing rail, a clock or reset problem, or a fault on a rail that causes the sequence to abort.","Current rises and then stays fixed without changing: boot may be stuck early, for example the SoC is not loading from storage.","Current rises and varies as if booting, then drops and the cycle repeats: a boot loop. Firmware, storage, RAM and power problems can all cause this."]},{"type":"example","title":"Worked reasoning (simulated scenario, not a real measurement)","steps":["Simulated scenario: a phone appears dead after liquid exposure.","On the bench supply, current flows immediately on connection, before pressing power, and reaches the limit you set.","This pattern points to a short on the main supply line or something connected to it.","Next step: disconnect power, check that line in diode mode, then locate the shorted part."],"note":"This is a teaching scenario. Real readings depend on the model and must be compared with a known-good board."},{"type":"explorer","blockId":"pmic","text":"Each pattern maps to a stage of power-up. Review the PMIC and Clocks & Reset blocks in the Chipset Explorer."}]'::jsonb),
  ('power/buck-converters-and-ldos', 'power', 'buck-converters-and-ldos', 3, 'Buck converters and LDOs', 'How the PMIC makes each rail, and what failure looks like.', 12, 'intermediate', 'planned', '{}'::text[], '[]'::jsonb),
  ('power/charging-circuits', 'power', 'charging-circuits', 4, 'Charging circuits', 'The USB input path, protection and the charging IC.', 12, 'intermediate', 'planned', '{}'::text[], '[]'::jsonb),
  ('power/finding-shorts-on-rails', 'power', 'finding-shorts-on-rails', 5, 'Finding shorts on rails', 'Locating a shorted component safely and efficiently.', 14, 'intermediate', 'planned', '{}'::text[], '[]'::jsonb),
  ('power/power-key-and-power-on', 'power', 'power-key-and-power-on', 6, 'The power key and power-on trigger', 'How a key press reaches the PMIC.', 8, 'beginner', 'planned', '{}'::text[], '[]'::jsonb),
  ('power/battery-connector-and-protection', 'power', 'battery-connector-and-protection', 7, 'Battery connector and protection', 'Battery lines, temperature/ID and protection circuits.', 10, 'intermediate', 'planned', '{}'::text[], '[]'::jsonb),
  ('boot/what-happens-when-you-press-power', 'boot', 'what-happens-when-you-press-power', 1, 'What happens when you press power', 'The stages a phone goes through from the power key to the operating system, and how to use them to narrow down a fault.', 12, 'beginner', 'published', array['List the main boot stages in order', 'Link each stage to the blocks involved', 'Use the stage where boot stops to narrow down a fault']::text[], '[{"type":"text","text":"Booting is a relay race. Each stage must finish before the next can start. If you can tell which stage the phone reaches, you have already ruled out a large part of the board."},{"type":"diagram","diagram":"boot-sequence","caption":"Conceptual boot sequence. The exact order, and which chip handles each step, varies by platform."},{"type":"heading","text":"Stage by stage"},{"type":"list","ordered":true,"items":["Power key: pressing it signals the power-management circuit. On many designs the key line goes to the PMIC; check the schematic.","Power-on sequence: supply rails are switched on in a defined order.","Clocks start: reference clocks begin running.","Reset released: once rails and clocks are ready, the SoC is released from reset.","Boot ROM: code built permanently into the SoC runs first and looks for the first bootloader in storage. If it can''t load one, many SoCs offer an emergency USB download mode.","Bootloaders: load from storage, initialise RAM, and check the software that follows. On most phones this chain is protected by digital signatures.","Operating system: the kernel and OS start, and drivers bring up the display, touch, cameras, radios and the rest."]},{"type":"callout","tone":"key","title":"Use the stage to narrow the fault","text":"If boot stops very early (no rails, no clock), suspect power and timing. If the boot ROM runs but no bootloader loads, suspect storage, its supply, or firmware. If the logo appears but the OS never finishes starting, firmware, storage and RAM are common suspects. Peripheral faults usually show only once the OS is running."},{"type":"heading","text":"Signs you can observe"},{"type":"list","items":["The current pattern on a bench power supply (see the power systems course).","Whether a computer detects the phone, and in which mode.","Whether the logo appears, and how far the boot animation gets.","A vibration at power-on, on phones that do this."]},{"type":"explorer","blockId":"soc","text":"See how the SoC depends on the PMIC, clocks, RAM and storage in the Chipset Explorer."}]'::jsonb),
  ('boot/boot-rom-and-download-modes', 'boot', 'boot-rom-and-download-modes', 2, 'Boot ROM and download modes', 'What emergency USB modes tell you about the board.', 10, 'intermediate', 'planned', '{}'::text[], '[]'::jsonb),
  ('boot/bootloaders-and-secure-boot', 'boot', 'bootloaders-and-secure-boot', 3, 'Bootloaders and secure boot', 'The signed chain from boot ROM to OS.', 12, 'intermediate', 'planned', '{}'::text[], '[]'::jsonb),
