  ('memory/lpddr-basics', 'memory', 'lpddr-basics', 1, 'LPDDR RAM basics', 'What RAM does during boot and while running.', 10, 'intermediate', 'planned', '{}'::text[], '[]'::jsonb),
  ('memory/emmc-vs-ufs', 'memory', 'emmc-vs-ufs', 2, 'eMMC vs UFS storage', 'Two storage types and how they differ for repair.', 10, 'intermediate', 'planned', '{}'::text[], '[]'::jsonb),
  ('memory/pop-and-mcp-packages', 'memory', 'pop-and-mcp-packages', 3, 'Stacked and combined packages', 'PoP, eMCP and uMCP explained.', 10, 'intermediate', 'planned', '{}'::text[], '[]'::jsonb),
