  ('diagnosis/interviewing-the-customer', 'diagnosis', 'interviewing-the-customer', 2, 'Getting the fault history', 'Questions that save hours of bench time.', 8, 'beginner', 'planned', '{}'::text[], '[]'::jsonb),
